/// A number of a fixture; non-finite numbers are the strings "inf", "-inf"
/// and "nan".
#[derive(Debug, Clone, Copy)]
struct F(f64);

impl<'de> Deserialize<'de> for F {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        #[derive(Deserialize)]
        #[serde(untagged)]
        enum Raw {
            F(f64),
            S(String),
        }
        Ok(F(match Raw::deserialize(d)? {
            Raw::F(v) => v,
            Raw::S(s) => match s.as_str() {
                "inf" => f64::INFINITY,
                "-inf" => f64::NEG_INFINITY,
                "nan" => f64::NAN,
                other => return Err(serde::de::Error::custom(format!("not a number: {other}"))),
            },
        }))
    }
}

fn vals(v: &[F]) -> Vec<f64> {
    v.iter().map(|f| f.0).collect()
}

fn fmat(rows: &[Vec<F>]) -> Matrix {
    let n = rows.len();
    let d = rows.first().map_or(0, |r| r.len());
    Matrix::from_fn(n, d, |i, j| rows[i][j].0)
}

