fn fixture_dir() -> PathBuf {
    common::fixture_dir().join("phase5c_entropy")
}

fn load_json<T: DeserializeOwned>(name: &str) -> T {
    let path = fixture_dir().join(name);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "{}: {e}; run scripts/generate_fixtures.py --phase 5c-entropy",
            path.display()
        )
    });
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

/// The per-model fixtures (sorted by name).
fn load() -> Vec<Fixture> {
    let mut names: Vec<String> = std::fs::read_dir(fixture_dir())
        .expect("phase-5c-entropy fixture directory exists")
        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
        .filter(|n| n.ends_with(".json") && n != "estimators.json")
        .collect();
    names.sort();
    assert!(names.len() >= 5, "phase-5c-entropy fixtures are missing");
    names.iter().map(|n| load_json(n)).collect()
}

// ---------------------------------------------------------------------------
// Builders
// ---------------------------------------------------------------------------

fn build_member(f: &ModelSpec) -> BatchedMultiOutputGP {
    let c = &f.config;
    let x: Vec<Matrix> = f.train_x.iter().map(|b| matrix(b)).collect();
    let y: Vec<Matrix> = f.train_y.iter().map(|b| matrix(b)).collect();
    let mut options = BatchedMultiOutputGPOptions {
        train_yvar: f
            .train_yvar
            .as_ref()
            .map(|v| v.iter().map(|b| matrix(b)).collect()),
        ..Default::default()
    };
    match c.covar.as_str() {
        "rbf" => {}
        "matern" => options.kernel = KernelKind::Matern52,
        "matern_gamma" => options.covar_module = Some(get_matern_kernel_with_gamma_prior(c.d)),
        other => panic!("unknown covar {other}"),
    }
    options.input_transform = match c.normalize.as_deref() {
        None => None,
        Some("shared") => Some(BatchedInputTransform::Shared(Normalize::new(c.d))),
        Some(other) => panic!("unknown normalize {other}"),
    };
    if c.outcome == "none" {
        options.outcome_transform = OutcomeTransformChoice::None;
    }
    let mut model = BatchedMultiOutputGP::new(x, y, vec![], options).unwrap();
    assert_eq!(model.num_outputs(), c.m);
    model.set_raw_parameters(&f.raw_params).unwrap();
    model
}

fn build_model(f: &Fixture) -> Arc<dyn Model> {
    let members: Vec<BatchedMultiOutputGP> = f.models.iter().map(build_member).collect();
    match f.kind.as_str() {
        "single_task" => Arc::new(members.into_iter().next().unwrap()),
        "model_list" => Arc::new(ModelListGP::new(members).unwrap()),
        other => panic!("unknown kind {other}"),
    }
}

fn matrices3(v: &[Vec<Vec<F>>]) -> Vec<Matrix> {
    v.iter().map(|m| fmat(m)).collect()
}

/// Hypercell bounds from BoTorch's flat `P x 2 x J x M` tensor.
fn cell_bounds(shape: &[usize], flat: &[f64]) -> CellBounds {
    let (p, j, m) = (shape[0], shape[2], shape[3]);
    let block = j * m;
    let mut lower = Vec::with_capacity(p * block);
    let mut upper = Vec::with_capacity(p * block);
    for k in 0..p {
        lower.extend_from_slice(&flat[(2 * k) * block..(2 * k + 1) * block]);
        upper.extend_from_slice(&flat[(2 * k + 1) * block..(2 * k + 2) * block]);
    }
    CellBounds::new(vec![p], j, m, lower, upper).unwrap()
}

/// The hypercell bounds of the sampled fronts (BoTorch's default).
fn fixture_cells(f: &Fixture) -> CellBounds {
    let b = &f.boxes[0];
    assert!(b.maximize && b.num_constraints == 0);
    cell_bounds(&b.shape, &vals(&b.bounds))
}

/// `rel_err` over the entries where the expected value is finite.
fn finite_rel_err(actual: &[f64], expected: &[f64], atol: f64) -> f64 {
    let (a, e): (Vec<f64>, Vec<f64>) = actual
        .iter()
        .zip(expected)
        .filter(|(_, e)| e.is_finite())
        .map(|(&a, &e)| {
            if (a - e).abs() <= atol {
                (e, e)
            } else {
                (a, e)
            }
        })
        .unzip();
    if e.is_empty() {
        0.0
    } else {
        rel_err(&a, &e)
    }
}

// ---------------------------------------------------------------------------
// Pathwise sampling
// ---------------------------------------------------------------------------

#[test]
fn matheron_paths_match_botorch() {
    let mut report = Report::default();
    for f in load() {
        let model = build_model(&f);
        let p = &f.paths;
        let options = MatheronPathOptions {
            draws: Some(p.draws.iter().map(Draws::draws).collect()),
            ..Default::default()
        };
        let paths = draw_matheron_paths(model.as_ref(), p.num_samples, &options).unwrap();
        let x = matrix(&p.x);
        let values = paths.forward(&x).unwrap();
        let (vg, grads) = paths.forward_with_grad(&x).unwrap();
        for (t, v) in values.iter().enumerate() {
            let expected = flat2(&p.values[t]);
            report.check_slices(
                &f.name,
                "path values",
                &matrix_rows(v),
                &expected,
                VALUE_TOL,
            );
            report.check_slices(
                &f.name,
                "path values (with grad)",
                &matrix_rows(&vg[t]),
                &expected,
                VALUE_TOL,
            );
            for (gs, es) in grads[t].iter().zip(&p.grads[t]) {
                let e = flat2(es);
                let a = matrix_rows(gs);
                report.check(
                    &f.name,
                    "path gradients",
                    finite_rel_err(&a, &e, GRAD_ATOL),
                    GRAD_TOL,
                );
            }
        }
        // The update weights (K + Σ)⁻¹ (y - f(X) - ε) of every output.
        let gps = model.output_gps().unwrap();
        for (t, gp) in gps.iter().enumerate() {
            let mp = MatheronPath::new(gp, p.draws[t].draws()).unwrap();
            let w = mp.update_paths().weight();
            report.check_slices(
                &f.name,
                "update weights",
                &matrix_rows(w),
                &flat2(&p.update_weights[t]),
                VALUE_TOL,
            );
        }
        // Prior paths with the outcome transform (`draw_kernel_feature_paths`).
        let prior_options = MatheronPathOptions {
            draws: Some(
                p.prior_draws
                    .iter()
                    .zip(&gps)
                    .map(|(d, gp)| MatheronPathDraws {
                        frequencies: fmat(&d.frequencies),
                        weights: fmat(&d.weights),
                        noise: Matrix::zeros(p.num_samples, gp.num_train()),
                    })
                    .collect(),
            ),
            ..Default::default()
        };
        let prior =
            draw_kernel_feature_paths(model.as_ref(), p.num_samples, &prior_options).unwrap();
        for (t, v) in prior.forward(&x).unwrap().iter().enumerate() {
            report.check_slices(
                &f.name,
                "prior path values",
                &matrix_rows(v),
                &flat2(&p.prior_values[t]),
                VALUE_TOL,
            );
        }
    }
    report.finish("Matheron paths vs BoTorch");
}

fn flat2(v: &[Vec<F>]) -> Vec<f64> {
    v.iter().flatten().map(|f| f.0).collect()
}

#[test]
fn sampled_optimal_points_match_botorch() {
    let mut report = Report::default();
    for f in load() {
        let model = build_model(&f);
        let o = &f.optima;
        let options = SampleOptimalPointsOptions {
            random_search: RandomSearchOptions {
                pop_size: o.pop_size,
                max_tries: o.max_tries,
                ..Default::default()
            },
            draws: Some(
                o.draws
                    .iter()
                    .map(|per_sample| per_sample.iter().map(Draws::draws).collect())
                    .collect(),
            ),
            candidates: Some(o.candidates.iter().map(|c| matrices3(c)).collect()),
            ..Default::default()
        };
        let (ps, pf) = sample_optimal_points(
            model.as_ref(),
            &matrix(&f.bounds),
            o.num_samples,
            o.num_points,
            o.maximize,
            &options,
        )
        .unwrap();
        let eps = matrices3(&o.pareto_sets);
        let efs = matrices3(&o.pareto_fronts);
        for k in 0..o.num_samples {
            // Identical selections: the Pareto sets are copies of candidates.
            let identical = ps[k] == eps[k];
            report.check(
                &f.name,
                "Pareto sets (identical)",
                if identical { 0.0 } else { 1.0 },
                0.0,
            );
            report.check_slices(
                &f.name,
                "Pareto fronts",
                &matrix_rows(&pf[k]),
                &matrix_rows(&efs[k]),
                VALUE_TOL,
            );
        }
    }
    report.finish("sample_optimal_points vs BoTorch");
}

#[test]
fn sample_box_decompositions_match_botorch() {
    let mut report = Report::default();
    for f in load() {
        for b in &f.boxes {
            let fronts = matrices3(&b.fronts);
            let cells = compute_sample_box_decomposition(
                &fronts,
                SamplePartitioning::Dominated,
                b.maximize,
                b.num_constraints,
            )
            .unwrap();
            let shape = vec![
                cells.batch_size(),
                2,
                cells.num_cells(),
                cells.num_outcomes(),
            ];
            let ok_shape = shape == b.shape;
            report.check(
                &f.name,
                "box shapes (identical)",
                if ok_shape { 0.0 } else { 1.0 },
                0.0,
            );
            if !ok_shape {
                continue;
            }
            let expected = cell_bounds(&b.shape, &vals(&b.bounds));
            let identical = cells.lower() == expected.lower() && cells.upper() == expected.upper();
            report.check(
                &f.name,
                "box bounds (identical)",
                if identical { 0.0 } else { 1.0 },
                0.0,
            );
        }
    }
    report.finish("compute_sample_box_decomposition vs BoTorch");
}

