// Entropy estimators
// ---------------------------------------------------------------------------

#[test]
fn entropy_estimators_match_botorch() {
    let est: Estimators = load_json("estimators.json");
    let mut report = Report::default();
    for c in &est.cases {
        let (b, p, q, j, s) = (c.shape[0], c.shape[1], c.shape[2], c.shape[3], c.shape[4]);
        let m = c.m;
        let mut lower = Vec::new();
        let mut upper = Vec::new();
        for k in 0..p {
            lower.extend(c.hypercell_bounds[k][0].iter().flatten().map(|f| f.0));
            upper.extend(c.hypercell_bounds[k][1].iter().flatten().map(|f| f.0));
        }
        let cells = CellBounds::new(vec![p], j, m, lower, upper).unwrap();
        let name = format!("m{m}");
        for (kind, res) in &c.results {
            let et = EstimationType::from_name(kind).unwrap();
            for bi in 0..b {
                for qi in 0..q {
                    let get = |t: &T5| Matrix::from_fn(p, m, |k, o| t[bi][k][qi][0][o].0);
                    let stats = EntropyStatistics {
                        mean: get(&c.mean),
                        variance: get(&c.variance),
                        observation_noise: get(&c.noise),
                    };
                    let samples: Vec<Matrix> = (0..p)
                        .map(|k| Matrix::from_fn(s, m, |si, o| c.samples[si][bi][k][qi][0][o].0))
                        .collect();
                    let lp = Matrix::from_fn(s, p, |si, k| c.log_prob[si][bi][k][qi].0);
                    let mc =
                        (et == EstimationType::MonteCarlo).then_some((samples.as_slice(), &lp));
                    let (h, g) = compute_entropy_with_grad(et, &cells, &stats, mc).unwrap();
                    let q_name = format!("{name} {kind}");
                    report.check_slices(
                        &q_name,
                        "estimator values",
                        &[h],
                        &[res.values[bi][qi].0],
                        VALUE_TOL,
                    );
                    let mut actual = Vec::new();
                    let mut expected = Vec::new();
                    for (gm, e) in [
                        (&g.mean, &res.grad_mean),
                        (&g.variance, &res.grad_variance),
                        (&g.observation_noise, &res.grad_noise),
                    ] {
                        actual.extend(matrix_rows(gm));
                        expected.extend(
                            (0..p)
                                .flat_map(|k| (0..m).map(move |o| (k, o)))
                                .map(|(k, o)| e[bi][k][qi][0][o].0),
                        );
                    }
                    if let (Some(gs), Some(es), Some(gl), Some(el)) = (
                        &g.samples,
                        &res.grad_samples,
                        &g.samples_log_prob,
                        &res.grad_log_prob,
                    ) {
                        for k in 0..p {
                            for si in 0..s {
                                for o in 0..m {
                                    actual.push(gs[k][(si, o)]);
                                    expected.push(es[si][bi][k][qi][0][o].0);
                                }
                                actual.push(gl[(si, k)]);
                                expected.push(el[si][bi][k][qi].0);
                            }
                        }
                    }
                    report.check(
                        &q_name,
                        "estimator gradients",
                        finite_rel_err(&actual, &expected, GRAD_ATOL),
                        GRAD_TOL,
                    );
                }
            }
        }
    }
    let lc = &est.log_cdf_robust;
    let actual: Vec<f64> = vals(&lc.x).into_iter().map(log_cdf_robust).collect();
    report.check_slices(
        "grid",
        "log_cdf_robust",
        &actual,
        &vals(&lc.values),
        VALUE_TOL,
    );
    report.finish("entropy estimators vs BoTorch");
}

// ---------------------------------------------------------------------------
// MES and JES
// ---------------------------------------------------------------------------

#[test]
fn mes_and_jes_match_botorch() {
    let mut report = Report::default();
    for f in load() {
        let model = build_model(&f);
        let cells = fixture_cells(&f);
        let ps = matrices3(&f.optima.pareto_sets);
        let pf = matrices3(&f.optima.pareto_fronts);
        for c in &f.acqf {
            let et = EstimationType::from_name(&c.estimation_type).unwrap();
            let sampler = c.base_samples.as_ref().map(|z| {
                let z = fmat(z);
                let s = SobolQMCNormalSampler::new(z.nrows(), Some(4242)).unwrap();
                s.set_base_samples(z).unwrap();
                Arc::new(s)
            });
            let options = LowerBoundMultiObjectiveEntropySearchOptions {
                x_pending: c.x_pending.as_ref().map(|p| matrix(p)),
                estimation_type: et,
                sampler,
            };
            let acqf: Box<dyn AcquisitionFunction> = match c.acqf.as_str() {
                "MES" => Box::new(
                    QLowerBoundMultiObjectiveMaxValueEntropySearch::new(
                        model.clone(),
                        cells.clone(),
                        options,
                    )
                    .unwrap(),
                ),
                "JES" => {
                    match QLowerBoundMultiObjectiveJointEntropySearch::new(
                        model.clone(),
                        ps.clone(),
                        pf.clone(),
                        cells.clone(),
                        options,
                    ) {
                        Ok(a) => Box::new(a),
                        Err(e) => {
                            let expected = c.error.as_deref().unwrap_or("<no error>");
                            let same = matches!(&e, BotorchError::Runtime(msg) if msg == expected);
                            report.check(
                                &f.name,
                                "JES errors (identical)",
                                if same { 0.0 } else { 1.0 },
                                0.0,
                            );
                            continue;
                        }
                    }
                }
                other => panic!("unknown acquisition function {other}"),
            };
            assert!(
                c.error.is_none(),
                "{}: BoTorch failed but botorch_core did not: {:?}",
                f.name,
                c.error
            );
            let label = format!("{} {}", c.acqf, c.estimation_type);
            let expected_values = vals(c.values.as_ref().unwrap());
            let expected_grads: Vec<f64> = c
                .grads
                .as_ref()
                .unwrap()
                .iter()
                .flat_map(|g| flat2(g))
                .collect();
            // Values near zero are differences of entropies of order one, so
            // values and gradients are compared normwise over the t-batch,
            // and against 10 times BoTorch's own change under 1e-14
            // perturbations of the training inputs where that is larger.
            let mut values = Vec::new();
            let mut values_g = Vec::new();
            let mut grads = Vec::new();
            for xb in &c.x {
                let x = matrix(xb);
                values.push(acqf.forward(&x).unwrap());
                let (vg, g) = acqf.forward_with_grad(&x).unwrap();
                values_g.push(vg);
                grads.extend(matrix_rows(&g));
            }
            let floor = c.floor.as_ref().unwrap();
            let (tv, tg) = (
                VALUE_TOL.max(10.0 * floor.value),
                GRAD_TOL.max(10.0 * floor.grad),
            );
            report.check_slices(
                &f.name,
                &format!("{label} values"),
                &values,
                &expected_values,
                tv,
            );
            report.check_slices(
                &f.name,
                &format!("{label} values (with grad)"),
                &values_g,
                &expected_values,
                tv,
            );
            report.check(
                &f.name,
                &format!("{label} gradients"),
                finite_rel_err(&grads, &expected_grads, GRAD_ATOL),
                tg,
            );
        }
    }
    report.finish("MES and JES vs BoTorch");
}

// ---------------------------------------------------------------------------
// PES
// ---------------------------------------------------------------------------

/// PES against BoTorch: where BoTorch's EP is stable (its twins with
/// perturbed training inputs take the same number of iterations), the
/// iteration counts must be identical and the cached factors, values and
/// gradients agree to the nominal tolerances or 10 times BoTorch's own
/// change; where EP depends on rounding (the twins disagree), the values
/// are only checked against BoTorch's own spread (a gross-failure check).
#[test]
fn pes_matches_botorch() {
    let mut report = Report::default();
    for f in load() {
        let model = build_model(&f);
        let ps = matrices3(&f.optima.pareto_sets);
        let m = model.num_outputs();
        for (ci, c) in f.pes.iter().enumerate() {
            let label = format!("PES {}", if c.maximize { "max" } else { "min" });
            let options = QMultiObjectivePredictiveEntropySearchOptions {
                maximize: c.maximize,
                x_pending: c.x_pending.as_ref().map(|p| matrix(p)),
                ..Default::default()
            };
            let acqf =
                QMultiObjectivePredictiveEntropySearch::new(model.clone(), ps.clone(), options);
            if let Some(err) = &c.error {
                report.check(
                    &f.name,
                    &format!("{label} errors ({err})"),
                    if acqf.is_err() { 0.0 } else { 1.0 },
                    0.0,
                );
                continue;
            }
            let acqf = acqf.unwrap_or_else(|e| panic!("{} case {ci}: {e}", f.name));
            let floor = c.floor.as_ref().unwrap();
            let stable = floor.iterations.iter().all(|&i| i == floor.iterations[0]);
            let expected_values = vals(c.values.as_ref().unwrap());
            let expected_grads: Vec<f64> = c
                .grads
                .as_ref()
                .unwrap()
                .iter()
                .flat_map(|g| flat2(g))
                .collect();
            let mut values = Vec::new();
            let mut grads = Vec::new();
            for xb in &c.x {
                let x = matrix(xb);
                let v = acqf.forward(&x).unwrap();
                let (vg, g) = acqf.forward_with_grad(&x).unwrap();
                assert_eq!(v, vg);
                values.push(v);
                grads.extend(matrix_rows(&g));
            }
            if !stable {
                // BoTorch's own EP iterates depend on rounding here.
                report.check(
                    &f.name,
                    &format!("{label} values (unstable EP, gross)"),
                    rel_err(&values, &expected_values),
                    (10.0 * floor.value).max(0.5),
                );
                continue;
            }
            let iterations = acqf.ep_summary().iterations;
            report.check(
                &f.name,
                &format!("{label} EP iterations (identical)"),
                if Some(iterations) == c.iterations {
                    0.0
                } else {
                    1.0
                },
                0.0,
            );
            // The cached factors of the Pareto rows.
            let (om, oc) = (
                c.omega_nat_mean.as_ref().unwrap(),
                c.omega_nat_cov.as_ref().unwrap(),
            );
            let mut a = Vec::new();
            let mut e = Vec::new();
            for (s, ps_s) in om.iter().enumerate() {
                for (t, om_t) in ps_s.iter().enumerate() {
                    let cache = &acqf.cached_factors()[s * m + t];
                    for (r, row) in om_t.iter().enumerate() {
                        for (k, mean) in row.iter().enumerate() {
                            a.extend(cache.cov(r, k));
                            e.extend(oc[s][t][r][k].iter().flatten().map(|v| v.0));
                            a.extend(cache.mean(r, k));
                            e.extend(mean.iter().map(|v| v.0));
                        }
                    }
                }
            }
            report.check(
                &f.name,
                &format!("{label} cached EP factors"),
                finite_rel_err(&a, &e, GRAD_ATOL),
                VALUE_TOL.max(10.0 * floor.omega),
            );
            report.check_slices(
                &f.name,
                &format!("{label} values"),
                &values,
                &expected_values,
                VALUE_TOL.max(10.0 * floor.value),
            );
            report.check(
                &f.name,
                &format!("{label} gradients"),
                finite_rel_err(&grads, &expected_grads, GRAD_ATOL),
                GRAD_TOL.max(10.0 * floor.grad),
            );
        }
    }
    report.finish("PES vs BoTorch");
}

fn vector(v: &[F]) -> botorch_core::Vector {
    botorch_core::Vector::from_iterator(v.len(), v.iter().map(|f| f.0))
}

/// EP factors from BoTorch's `R x P x 2` and `R x P x 2 x 2` arrays.
fn factors(mean: &V3, cov: &T4) -> EpFactors {
    let (rows, p) = (mean.len(), mean[0].len());
    let m: Vec<f64> = mean.iter().flatten().flatten().map(|f| f.0).collect();
    let c: Vec<f64> = cov
        .iter()
        .flatten()
        .flatten()
        .flatten()
        .map(|f| f.0)
        .collect();
    EpFactors::from_values(rows, p, m, c).unwrap()
}

/// The steps of BoTorch's EP iterations from BoTorch's inputs: the factor
/// update (every factor within 1e-9 or 10 times its change under last-bit
/// noise in exp and erf, which the cancellations of the update amplify),
/// the marginal update, the damping update (identical damping factors) and
/// the convergence test (identical decisions).
#[test]
fn ep_steps_match_botorch() {
    let mut report = Report::default();
    let mut cases = 0;
    for f in load() {
        let Some(ep) = &f.ep_steps else {
            continue;
        };
        for c in ep {
            for st in &c.steps {
                cases += 1;
                let label = format!(
                    "{} EP it {}",
                    if c.maximize { "max" } else { "min" },
                    st.iteration
                );
                let o = &st.omega;
                let (ns, m) = (o.mean_f.len(), o.mean_f[0].len());
                // `_update_omega`.
                let mut worst = 0.0f64;
                let mut floored = 0usize;
                for s in 0..ns {
                    let means: Vec<botorch_core::Vector> =
                        o.mean_f[s].iter().map(|v| vector(v)).collect();
                    let covs: Vec<Matrix> = o.cov_f[s].iter().map(|c| fmat(c)).collect();
                    let omegas: Vec<EpFactors> = (0..m)
                        .map(|t| factors(&o.omega_mean[s][t], &o.omega_cov[s][t]))
                        .collect();
                    let out = update_omega(
                        &means.iter().collect::<Vec<_>>(),
                        &covs.iter().collect::<Vec<_>>(),
                        &omegas.iter().collect::<Vec<_>>(),
                        o.N,
                        o.P,
                        c.maximize,
                        o.jitter,
                    )
                    .expect("BoTorch's update succeeded");
                    for (t, out_t) in out.iter().enumerate() {
                        for r in 0..o.N + o.P {
                            for k in 0..o.P {
                                if r == o.N + k {
                                    continue; // the Pareto diagonal is zeroed
                                }
                                let am = out_t.mean(r, k);
                                let ac = out_t.cov(r, k);
                                let em = &o.new_mean[s][t][r][k];
                                let ec = &o.new_cov[s][t][r][k];
                                let fm = &o.floor_mean[s][t][r][k];
                                let fc = &o.floor_cov[s][t][r][k];
                                let pairs = [
                                    (am[0], em[0].0, fm[0].0),
                                    (am[1], em[1].0, fm[1].0),
                                    (ac[0], ec[0][0].0, fc[0][0].0),
                                    (ac[1], ec[0][1].0, fc[0][1].0),
                                    (ac[2], ec[1][0].0, fc[1][0].0),
                                    (ac[3], ec[1][1].0, fc[1][1].0),
                                ];
                                for (a, e, fl) in pairs {
                                    let nominal = VALUE_TOL * e.abs().max(1.0);
                                    let tol = nominal.max(10.0 * fl);
                                    if tol > nominal {
                                        floored += 1;
                                    }
                                    worst = worst.max((a - e).abs() / tol);
                                }
                            }
                        }
                    }
                }
                report.check(
                    &f.name,
                    &format!("{label} factors (scaled)"),
                    worst * VALUE_TOL,
                    VALUE_TOL,
                );
                println!(
                    "{} {label}: {floored} factor entries use the last-bit floor",
                    f.name
                );
                // `_update_marginals`.
                let mg = &st.marginals;
                let mut a = Vec::new();
                let mut e = Vec::new();
                for s in 0..ns {
                    for t in 0..m {
                        let mut om = factors(&mg.omega_mean[s][t], &mg.omega_cov[s][t]);
                        let (nm, nc) = update_marginals(
                            &vector(&mg.pred_nat_mean[s][t]),
                            &fmat(&mg.pred_nat_cov[s][t]),
                            &mut om,
                            o.N,
                            o.P,
                        );
                        a.extend(nm.iter());
                        a.extend(matrix_rows(&nc));
                        e.extend(vals(&mg.nat_mean[s][t]));
                        e.extend(mg.nat_cov[s][t].iter().flatten().map(|v| v.0));
                    }
                }
                report.check_slices(&f.name, &format!("{label} marginals"), &a, &e, VALUE_TOL);
                // `_update_damping`.
                let dp = &st.damping;
                let olds: Vec<Matrix> = dp.nat_cov.iter().flatten().map(|c| fmat(c)).collect();
                let news: Vec<Matrix> = dp.nat_cov_new.iter().flatten().map(|c| fmat(c)).collect();
                let damping: Vec<f64> = dp.damping.iter().flatten().map(|v| v.0).collect();
                let (df, chols) = update_damping(
                    &olds.iter().collect::<Vec<_>>(),
                    &news.iter().collect::<Vec<_>>(),
                    &damping,
                    dp.jitter,
                )
                .unwrap();
                let edf: Vec<f64> = dp.new_damping.iter().flatten().map(|v| v.0).collect();
                report.check(
                    &f.name,
                    &format!("{label} damping (identical)"),
                    if df == edf { 0.0 } else { 1.0 },
                    0.0,
                );
                let ach: Vec<f64> = chols.iter().flat_map(matrix_rows).collect();
                let ech: Vec<f64> = dp
                    .cholesky
                    .iter()
                    .flatten()
                    .flatten()
                    .flatten()
                    .map(|v| v.0)
                    .collect();
                report.check_slices(
                    &f.name,
                    &format!("{label} damped Cholesky factors"),
                    &ach,
                    &ech,
                    VALUE_TOL,
                );
                // `_update_damping_when_converged`.
                let cv = &st.converged;
                let mut same = true;
                for s in 0..ns {
                    for t in 0..m {
                        let d = update_damping_when_converged(
                            &vector(&cv.mean_old[s][t]),
                            &vector(&cv.mean_new[s][t]),
                            &fmat(&cv.cov_old[s][t]),
                            &fmat(&cv.cov_new[s][t]),
                            cv.damping[s][t].0,
                            cv.iteration,
                            cv.threshold,
                        );
                        same &= d == cv.new_damping[s][t].0;
                    }
                }
                report.check(
                    &f.name,
                    &format!("{label} convergence (identical)"),
                    if same { 0.0 } else { 1.0 },
                    0.0,
                );
            }
        }
    }
    assert!(cases >= 4, "the EP step fixtures are missing");
    report.finish("EP steps vs BoTorch");
}
